contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 withdrawAmount) public payable {
        // Ensure the test contract has no deposited balance by attempting to withdraw 0 first;
        // a zero withdraw with zero balance succeeds and does not change the balance.
        bool reverted0;
        c.withdraw(0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted0 = true;
        } else {
            reverted0 = false;
        }

        uint256 beforeCBalance = address(c).balance;

        bool reverted;
        c.withdraw(withdrawAmount); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterCBalance = address(c).balance;

        assert(!reverted0 && reverted == (withdrawAmount > 0) && (reverted || afterCBalance == beforeCBalance));
    }

    receive() external payable {}
}

