// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 withdrawAmount) internal {
        bool reverted0;
        try c.withdraw(0) {
            reverted0 = false;
        } catch {
            reverted0 = true;
        }
        uint256 beforeCBalance = address(c).balance;
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCBalance = address(c).balance;
        assertTrue(!reverted0 && reverted == (withdrawAmount > 0) && (reverted || afterCBalance == beforeCBalance));
    }

    function testFuzz_run(uint256 withdrawAmount) public {
        _run(withdrawAmount);
    }

    receive() external payable {}
}
